// ---------------------------------------------------------------- Run
phase('Ground')
log(`Wave 1: ${GROUNDERS.length} grounders + ${SCOUTS.length} scouts, all sonnet, concurrent (cap applies)`)

const groundThunks = GROUNDERS.map(g => () =>
  agent(g.prompt, { label: `ground:${g.key}`, phase: 'Ground', model: 'sonnet', schema: GROUND_SCHEMA })
    .then(r => ({ key: g.key, ...r })))

const scoutThunks = SCOUTS.map(s => () =>
  agent(
    `${PREAMBLE('corpus survey and web reading — discovering topics, deciding nothing')}
${SCOUT_CONTRACT(s.corpus, `${RESEARCH}/jvm-topic-map/${s.key}.md`)}`,
    { label: `scout:${s.key}`, phase: 'Scout', model: 'sonnet', schema: SCOUT_SCHEMA },
  ).then(r => ({ key: s.key, ...r })))

const all = await parallel([...groundThunks, ...scoutThunks])
const ground = all.slice(0, GROUNDERS.length).filter(Boolean)
const scouts = all.slice(GROUNDERS.length).filter(Boolean)

const dropped = [
  ...GROUNDERS.filter((g, i) => !all[i]).map(g => `ground:${g.key}`),
  ...SCOUTS.filter((s, i) => !all[GROUNDERS.length + i]).map(s => `scout:${s.key}`),
]
if (dropped.length) log(`DROPPED (returned null): ${dropped.join(', ')}`)

const totalCandidates = scouts.reduce((n, s) => n + (s.candidates ? s.candidates.length : 0), 0)
log(`Ground: ${ground.length}/${GROUNDERS.length} · Scouts: ${scouts.length}/${SCOUTS.length} · candidates: ${totalCandidates}`)

return { ground, scouts, dropped, totalCandidates }
